    id: T;
    label: ReactNode;
    testId?: string;
    className?: string;
    disabled?: boolean;
    panel?: ReactNode;
    panelTestId?: string;
    panelClassName?: string;
    panelAs?: "div" | "section";
  };

  export type TabsProps<T extends string = string> = {
    items: readonly TabItem<T>[];
    value: T;
    onChange: (value: T) => void;
    label: string;
    testId?: string;
    idPrefix: string;
    className?: string;
    tablistClassName?: string;
    tabClassName?: string;
    panelsClassName?: string;
    panelsRef?: Ref<HTMLDivElement>;
    keepMounted?: boolean;
    panelAs?: "div" | "section";
  };
  ```
- Component `Tabs<T extends string = string>({ ... }: TabsProps<T>)`:
